'use strict';

const fs = require('fs-extra')

const { runPy } = require('../helper')

function createOutputDir(dir) {
  try {
    const stats = fs.lstatSync(dir)
    if (!stats.isDirectory()) {
      fs.unlinkSync(dir)
      throw new Error('The path exists, but not a directory')
    }
  } catch (err) {
    console.warn(err)
    fs.ensureDirSync(dir)
  }
}

/**
 *
 * @param {string | string[]} cameraId 
 * @param {{start: number, end: number}} options
 * @param {string} dir 
 * @returns void
 */
function saveAnalyticData(
  cameraId,
  {
    start,
    end = Date.now(),
    ...rest
  } = {},
  dir = './data',
) {
  createOutputDir(dir)

  if (!start) start = end - 60 * 60 * 1000

  const id = Array.isArray(cameraId)
    ? cameraId.join(',')
    : cameraId

  return runPy('save_analytic_data.py', {
    args: [
      '-id', id,
      '-out', dir,
      '-s', start,
      '-e', end,
    ],
    ...rest,
  })
}

module.exports = saveAnalyticData
